import {Trace} from './trace.mjs';
const main=(lines,headers='#include <stdio.h>',defs='')=>`${headers}\n${defs}\nint main(void)\n{\n${lines.map(l=>'    '+l).join('\n')}\n    return (0);\n}`;
const readOut=(b,at,text,what='Read the current values and append their formatted output.')=>b.step(at,'Print current data',what,'The output call does not modify the stored values.','data → terminal',()=>b.state.output+=text);
function allocation(){const b=new Trace('allocation','Allocation · ownership and free','malloc creates new storage whose lifetime is independent of a local pointer variable.',main(['int *p = malloc(3 * sizeof(*p));','if (p == NULL)','    return (1);','p[0] = 2;','p[1] = 3;','p[2] = 4;','printf("%d %d %d\\n", p[0], p[1], p[2]);','free(p);','p = NULL;'],'#include <stdio.h>\n#include <stdlib.h>'));b.step('int *p = malloc(3 * sizeof(*p));','Allocate three ints','Request enough storage for three ints. This example follows the successful allocation path.','sizeof(*p) obtains the pointed type’s size without dereferencing this uninitialized pointer. malloc storage starts uninitialized.','malloc → heap block address → p',()=>{b.ints('heap',[undefined,undefined,undefined],0x5000,'p','heap');b.ptr('p','p','int *',0x1000,'heap0');});b.step('if (p == NULL)','Check allocation success','p contains an allocated address, so p == NULL is false.','Always check before dereferencing an allocation result. The return (1) branch is skipped here.','p != NULL → continue',()=>{},['p']);for(let i=0;i<3;i++)b.step(`p[${i}] = ${i+2};`,'Initialize an allocated element',`Write ${i+2} into element ${i} of the allocated block.`,'The pointer remains at the start. Indexing calculates a relative element address.',`p + ${i} → heap element ← ${i+2}`,()=>b.set('heap'+i,i+2),['p'],['heap'+i]);readOut(b,'printf("%d %d %d\\n", p[0], p[1], p[2]);','2 3 4\n');b.step('free(p);','Release the heap block','Return the entire allocated block to the allocator.','p temporarily still stores the old address. That address is now invalid to dereference.','heap storage lifetime ends',()=>{for(let i=0;i<3;i++)delete b.state.cells['heap'+i];delete b.state.cells.p.target;b.state.cells.p.invalid=true;},['p']);b.step('p = NULL;','Clear the expired address','Replace p’s old address with NULL.','NULL is initialized but points to no object. Do not dereference it.','NULL → p',()=>{b.set('p','NULL');b.state.cells.p.invalid=false;});return b.finish('return (0);','','Finish without additional output.');}
function strdup(){const b=new Trace('strdup','Duplicate · return independent storage','A duplicate gets its own character cells and must be released by its owner.',main(['char src[] = "Hi";','char *copy = malloc(sizeof(src));','if (copy == NULL)','    return (1);','int i = 0;',"while (src[i] != '\\0')",'{','    copy[i] = src[i];','    i++;','}',"copy[i] = '\\0';","src[0] = 'B';",'printf("%s %s\\n", src, copy);','free(copy);','copy = NULL;'],'#include <stdio.h>\n#include <stdlib.h>'));b.step('char src[] = "Hi";','Create the source','Create H, i, and zero.','The duplicate will occupy separate storage.','chars → src',()=>b.chars('s','Hi',0x1000,'src'));b.step('char *copy = malloc(sizeof(src));','Allocate the duplicate','Allocate three chars, including room for the terminating zero.','This source is an array, so sizeof(src) is 3 here; sizeof on a pointer would measure the pointer itself.','malloc(3) → copy',()=>{for(let i=0;i<3;i++)b.cell('d'+i,`copy[${i}]`,'char',0x5000+i,undefined,'heap');b.ptr('copy','copy','char *',0x2000,'d0');});b.step('if (copy == NULL)','Check the new storage','Allocation succeeded in this example.','The failure branch returns before any dereference.','non-NULL → continue',()=>{},['copy']);b.step('int i = 0;','Initialize the index','Set i to 0.','One char is copied per iteration.','0 → i',()=>b.cell('i','i','int',0x2008,0));for(let i=0;i<2;i++){b.step("while (src[i] != '\\0')",'Check the current source char','The source char is not zero.','Source data stays unchanged during a copy.','true → copy',()=>{},['s'+i]);b.step('copy[i] = src[i];','Copy the char',`Copy '${'Hi'[i]}' into the allocated destination.`,'A value copy creates no live link between the char cells.','src char → copy char',()=>b.set('d'+i,'Hi'[i]),['s'+i,'copy']);b.step('i++;','Advance the index',`Set i to ${i+1}.`,'Continue to the next char.','i + 1 → i',()=>b.set('i',i+1));}b.step("while (src[i] != '\\0')",'Find the terminator','The current source char is zero.','Exit the character loop.','false → end',()=>{},['s2']);b.step("copy[i] = '\\0';",'Terminate the duplicate','Write a zero at copy[2].','The allocated bytes now form an independent valid C string.','zero → copy end',()=>b.set('d2','\\0'));b.step("src[0] = 'B';",'Modify only the source','Change src[0] from H to B.','The duplicate still says Hi because its characters were copied into independent cells.','B → src[0]',()=>b.set('s0','B'));readOut(b,'printf("%s %s\\n", src, copy);','Bi Hi\n');b.step('free(copy);','Release the duplicate','Free the allocated copy.','The source remains alive because it is main’s array, not this heap allocation.','copy heap lifetime ends',()=>{for(let i=0;i<3;i++)delete b.state.cells['d'+i];delete b.state.cells.copy.target;b.state.cells.copy.invalid=true;},['copy']);b.step('copy = NULL;','Clear the copy pointer','Set copy to NULL.','The pointer can no longer appear to reference a live block.','NULL → copy',()=>{b.set('copy','NULL');b.state.cells.copy.invalid=false;});return b.finish('return (0);','','End the example.');}
function pointerOutput(){const defs='void provide(int **out, int *storage)\n{\n    *out = storage;\n}';const b=new Trace('pointer-output','Pointer output · int **','To change a caller’s pointer variable, pass that pointer variable’s address.',main(['int data[2] = {7, 8};','int *result = NULL;','provide(&result, data);','printf("%d %d\\n", result[0], result[1]);'],'#include <stdio.h>\n#include <stdlib.h>',defs));b.step('int data[2] = {7, 8};','Create storage','Create two caller-owned integers.','This concept example uses existing storage to isolate the double-pointer mechanism. Allocation is demonstrated separately.','values → data array',()=>b.ints('d',[7,8],0x1000,'data'));b.step('int *result = NULL;','Create the output pointer','Initialize result to NULL.','We want the function to change this pointer object itself.','NULL → result',()=>b.cell('result','result','int *',0x2000,'NULL'));b.step('provide(&result, data);','Pass the pointer’s address','Copy &result into out and the array’s first address into storage.','out points to an int * object. One dereference reaches that pointer, not an int.','&result → out; &data[0] → storage',()=>{b.enter('provide');b.ptr('out','out','int **',0x3000,'result');b.ptr('storage','storage','int *',0x3008,'d0');});b.step('*out = storage;','Modify the caller pointer','Follow out to result and copy the address stored in storage into result.','The caller’s pointer changes from NULL to &data[0]. The integer data does not change.','storage’s address value → *out → result',()=>b.ptr('result','result','int *',0x2000,'d0','main'),['out','storage'],['result','d0']);b.step('}','Return to main','The function’s local pointer parameters leave scope.','result keeps the copied address and points into the still-live caller array.','return → main',()=>b.leave());return b.finish('printf("%d %d\\n", result[0], result[1]);','7 8\n');}
function concat(){const b=new Trace('strcat','Concatenation · preserve the prefix','Find the destination terminator, then append source chars and a new terminator.',main(['char dest[5] = "Hi";','char src[] = "!";','int end = 0;','int i = 0;',"while (dest[end] != '\\0')",'    end++;',"while (src[i] != '\\0')",'{','    dest[end + i] = src[i];','    i++;','}',"dest[end + i] = '\\0';",'printf("%s\\n", dest);']));b.step('char dest[5] = "Hi";','Create destination capacity','Initialize H, i, and zero-fill the remaining three chars.','Array initialization zero-fills unused elements. There is enough space for the append and its terminator.','Hi plus zero padding → dest',()=>{b.chars('d','Hi',0x1000,'dest','main',5);b.set('d3','\\0');b.set('d4','\\0');});b.step('char src[] = "!";','Create the suffix','Create ! and zero.','The suffix source is independent of the destination.','! → src',()=>b.chars('s','!',0x1100,'src'));for(const [id,loc]of [['end',0x2000],['i',0x2004]])b.step(`int ${id} = 0;`,'Initialize '+id,'Store zero.','end finds the prefix length; i scans the suffix.','0 → '+id,()=>b.cell(id,id,'int',loc,0));for(let i=0;i<2;i++){b.step("while (dest[end] != '\\0')",'Scan the existing prefix','The current destination char is not zero.','The original prefix remains intact.','nonzero → continue',()=>{},['d'+i]);b.step('end++;','Advance to the append position',`Set end to ${i+1}.`,'No destination bytes change yet.','end + 1 → end',()=>b.set('end',i+1));}b.step("while (dest[end] != '\\0')",'Find the original terminator','dest[2] is zero.','Appending begins at this position, replacing the old terminator.','zero → append point',()=>{},['d2']);b.step("while (src[i] != '\\0')",'Check the suffix','The source ! is nonzero.','One char needs to be copied.','true → copy',()=>{},['s0']);b.step('dest[end + i] = src[i];','Append the suffix char','Write ! at dest[2].','The prefix H and i is unchanged. A new terminator still has to be established.','src[0] → dest[2]',()=>b.set('d2','!'),['s0']);b.step('i++;','Advance source position','Set i to 1.','The following source cell is zero.','1 → i',()=>b.set('i',1));b.step("while (src[i] != '\\0')",'End the suffix copy','The source terminator stops the loop.','The terminator itself was not copied by the loop.','false → finish',()=>{},['s1']);b.step("dest[end + i] = '\\0';",'Terminate the new string','Write zero at dest[3].','The string is now Hi!. The cell was already zero from initialization, so its stored value stays the same.','zero → dest[3]',()=>b.set('d3','\\0'));return b.finish('printf("%s\\n", dest);','Hi!\n');}
function split(){const b=new Trace('split','Split · string boundaries and NULL sentinel','A string terminator and a pointer-array terminator are different kinds of zero.',main(['char text[] = "a,b";','char *parts[3];','parts[0] = text;',"text[1] = '\\0';",'parts[1] = &text[2];','parts[2] = NULL;','printf("%s %s\\n", parts[0], parts[1]);']));b.step('char text[] = "a,b";','Create the text','Create a, comma, b, and zero.','This in-place miniature example demonstrates token boundaries; the assignment’s allocated-result ownership is in its requirements and allocation lessons.','chars → text',()=>b.chars('t','a,b',0x1000,'text'));b.step('char *parts[3];','Create an array of pointers','Reserve three pointer cells.','These cells will hold addresses, not character data.','pointer slots created',()=>{for(let i=0;i<3;i++)b.cell('p'+i,`parts[${i}]`,'char *',0x2000+i*8,undefined);});b.step('parts[0] = text;','Point at the first token','Store &text[0] in parts[0].','No characters are copied.','first char address → parts[0]',()=>b.ptr('p0','parts[0]','char *',0x2000,'t0'));b.step("text[1] = '\\0';",'Terminate the first token','Replace the separator comma with a zero character.','parts[0] now names a one-character string a.','zero char → delimiter cell',()=>b.set('t1','\\0'));b.step('parts[1] = &text[2];','Point at the second token','Store &text[2] in parts[1].','The original end zero terminates token b.','second token address → parts[1]',()=>b.ptr('p1','parts[1]','char *',0x2008,'t2'));b.step('parts[2] = NULL;','Terminate the pointer list','Store a null pointer after the two token pointers.','NULL ends the pointer array; \\0 ends each character string. They have different types.','NULL pointer → parts[2]',()=>b.set('p2','NULL'));return b.finish('printf("%s %s\\n", parts[0], parts[1]);','a b\n');}
function substring(){const b=new Trace('strstr','Substring · an address inside existing text','A match can be returned as an interior pointer without creating new text.',main(['char text[] = "xxcat";','char *match = strstr(text, "cat");','if (match != NULL)','    printf("%s\\n", match);'],'#include <stdio.h>\n#include <string.h>'));b.step('char text[] = "xxcat";','Create the searchable text','Create xxcat and its terminator.','A successful match points into these same existing cells.','chars → text',()=>b.chars('t','xxcat',0x1000,'text'));b.step('char *match = strstr(text, "cat");','Search and return an interior address','The library search finds cat beginning at text[2] and returns that address.','This concept example treats the library call as one source operation. It demonstrates the return-address contract rather than the exercise’s internal search implementation.','&text[2] → match',()=>b.ptr('match','match','char *',0x2000,'t2'),['t0','t1','t2','t3','t4'],['match','t2']);b.step('if (match != NULL)','Check for a found result','The returned address is non-NULL.','A missing match would take the false path and must not be dereferenced.','non-NULL → output',()=>{},['match']);return b.finish('printf("%s\\n", match);','cat\n');}
function base(){const b=new Trace('base-conversion','Base conversion · remainders and reverse order','Repeated division extracts the least significant digit first.',main(['int n = 5;','char digits[4];','int i = 0;','while (n > 0)','{',"    digits[i] = '0' + n % 2;",'    n = n / 2;','    i++;','}','while (i > 0)','{','    i--;','    putchar(digits[i]);','}',"putchar('\\n');"]));b.step('int n = 5;','Create the decimal value','Store 5.','The same numeric value can be represented with different digit alphabets.','5 → n',()=>b.cell('n','n','int',0x2000,5));b.step('char digits[4];','Reserve digit storage','Create four uninitialized chars.','Only initialized positions will be printed, so no terminator is needed for these individual putchar calls.','digit buffer created',()=>{for(let i=0;i<4;i++)b.cell('d'+i,`digits[${i}]`,'char',0x1000+i,undefined);});b.step('int i = 0;','Start the digit count','Set i to zero.','i counts stored remainder digits.','0 → i',()=>b.cell('i','i','int',0x2004,0));let n=5;for(let i=0;i<3;i++){b.step('while (n > 0)','Check for more digits',`${n} > 0 is true.`,'Continue while division has not consumed the number.','true → body',()=>{},['n']);const digit=String(n%2);b.step("digits[i] = '0' + n % 2;",'Extract the next binary digit',`${n} % 2 is ${digit}; store printable '${digit}'.`,'The first extracted digit is the rightmost digit in the final representation.','remainder → digit char → buffer',()=>b.set('d'+i,digit),['n']);const next=Math.floor(n/2);b.step('n = n / 2;','Remove the extracted place',`${n} / 2 yields ${next} in integer division.`,'The remaining number will supply the next digit.','n / base → n',()=>b.set('n',next),['n']);n=next;b.step('i++;','Count the stored digit',`Set i to ${i+1}.`,'The stored digits will be read in reverse.','i + 1 → i',()=>b.set('i',i+1));}b.step('while (n > 0)','End the extraction','n is zero, so extraction stops.','Three digits were stored.','false → output',()=>{},['n']);for(let i=3;i>0;i--){b.step('while (i > 0)','Check remaining output digits',`${i} > 0 is true.`,'Print from the last stored position back to zero.','true → body',()=>{},['i']);b.step('i--;','Select the previous stored digit',`Set i to ${i-1}.`,'The decrement occurs before the buffer read.','i - 1 → i',()=>b.set('i',i-1));readOut(b,'putchar(digits[i]);','101'[3-i],`Read digits[${i-1}] and print it.`);}b.step('while (i > 0)','Stop printing','i is zero, so the loop is done.','The output is the binary representation of decimal 5.','false → end',()=>{},['i']);return b.finish("putchar('\\n');",'\n');}
function nonprintable(){const b=new Trace('nonprintable','Non-printable char · hex escape','Represent a byte using two hexadecimal digits.',main(["unsigned char value = '\\n';",'char hex[] = "0123456789abcdef";',"putchar('\\\\');",'putchar(hex[value / 16]);','putchar(hex[value % 16]);',"putchar('\\n');"]));b.step("unsigned char value = '\\n';",'Create a newline byte','Store newline’s code, 10 in this environment, as an unsigned char.','The newline itself would move the terminal cursor; this example prints its hexadecimal representation instead.','newline byte → value',()=>b.cell('value','value','unsigned char',0x2000,10));b.step('char hex[] = "0123456789abcdef";','Create the digit alphabet','Store the sixteen hex characters and a zero terminator.','A nibble value 0–15 selects its corresponding hex digit.','hex alphabet → char array',()=>b.chars('hex','0123456789abcdef',0x1000,'hex'));readOut(b,"putchar('\\\\');",'\\','Print a literal backslash.');readOut(b,'putchar(hex[value / 16]);','0','10 / 16 is zero; print hex[0].');readOut(b,'putchar(hex[value % 16]);','a','10 % 16 is 10; print hex[10], which is a.');return b.finish("putchar('\\n');",'\n');}
function argv(reverse=false){const b=new Trace(reverse?'argv-reverse':'argv',reverse?'Arguments · reverse visitation':'Arguments · argc and argv','argv is an array of pointers to strings. argc counts the program name and supplied arguments.',`#include <stdio.h>\nint main(int argc, char **argv)\n{\n    int i = ${reverse?'argc - 1':'1'};\n    while (i ${reverse?'> 0':'< argc'})\n    {\n        printf("%s\\n", argv[i]);\n        i${reverse?'--':'++'};\n    }\n    return (0);\n}`,{args:['red','blue']});b.cell('argc','argc','int',0x2000,3);b.chars('program','./example',0x1000,'program','arguments');b.chars('red','red',0x1100,'arg1','arguments');b.chars('blue','blue',0x1200,'arg2','arguments');['program0','red0','blue0'].forEach((t,i)=>b.ptr('a'+i,`argv[${i}]`,'char *',0x3000+i*8,t,'arguments'));b.cell('a3','argv[3]','char *',0x3018,'NULL','arguments');b.cell('argv','argv','char **',0x4000,'0x3000','main',{target:'a0'});b.steps=[];b.capture(0,'Program receives arguments','Run ./example red blue. argc is 3 and argv[argc] is NULL.','argv[0] is the program name; the user arguments begin at index 1.','command-line text → argc and argv');const init=reverse?'int i = argc - 1;':'int i = 1;',cond=reverse?'while (i > 0)':'while (i < argc)',op=reverse?'i--;':'i++;';b.step(init,'Choose the starting argument',`Initialize i to ${reverse?2:1}.`,'The program name is skipped in this example.','starting index → i',()=>b.cell('i','i','int',0x2004,reverse?2:1));for(const i of reverse?[2,1]:[1,2]){b.step(cond,'Check the argument index','The current index is within the chosen user-argument range.','The argv pointer and strings stay unchanged.','condition → true',()=>{},['i','argc']);readOut(b,'printf("%s\\n", argv[i]);',`${i===1?'red':'blue'}\n`,`Read argv[${i}], follow its char address, and print that string.`);b.step(op,'Move the argument index',`Set i to ${i+(reverse?-1:1)}.`,'Only the local index changes.','index update → i',()=>b.set('i',i+(reverse?-1:1)));}b.step(cond,'Stop at the boundary','No more user arguments remain in this direction.','Never read past argv[argc].','condition → false',()=>{},['i']);return b.finish('return (0);','','Finish without additional output.');}
function callback(){const defs='int doubled(int value)\n{\n    return (value * 2);\n}';const b=new Trace('callback','Function pointer · copied code address','A function pointer selects which function to call.',main(['int (*fn)(int) = doubled;','int result = fn(5);','printf("%d\\n", result);'],'#include <stdio.h>',defs));b.step('int (*fn)(int) = doubled;','Store the function address','Initialize fn with the address of doubled.','The parentheses make fn a pointer to a function taking an int and returning an int.','doubled code address → fn',()=>{b.cell('code','doubled','function',0xF000,'int → int','code');b.ptr('fn','fn','int (*)(int)',0x2000,'code');});b.step('int result = fn(5);','Call through the function pointer','Follow fn’s function address and pass a copy of 5.','This calls code; it does not read an int object through a data pointer.','fn → doubled; 5 → value',()=>{b.enter('doubled');b.cell('value','value','int',0x3000,5);},['fn']);b.step('return (value * 2);','Compute the callback return','5 × 2 is 10. Return that integer value.','The parameter belongs to the callback; main receives the returned value.','10 → waiting caller',()=>{},['value']);b.leave();b.step('int result = fn(5);','Receive the result','Initialize result with the returned 10.','The callback’s parameter has left scope.','return value → main.result',()=>b.cell('result','result','int',0x1000,10));return b.finish('printf("%d\\n", result);','10\n');}
function struct(){const defs='typedef struct s_point\n{\n    int x;\n    int y;\n} t_point;';const b=new Trace('structure','Structures · a record and its address','A struct groups fields. A pointer can access the same record with ->.',main(['t_point point = {1, 2};','t_point *p = &point;','p->x = 7;','printf("%d %d\\n", point.x, point.y);'],'#include <stdio.h>',defs));b.step('t_point point = {1, 2};','Create the record','Initialize one struct with x = 1 and y = 2.','The typedef names the type; point names an actual object of that type.','field values → point',()=>b.cell('point','point','t_point',0x1000,'{x: 1, y: 2}'));b.step('t_point *p = &point;','Copy the record’s address','Initialize p with &point.','p->x means (*p).x. The pointer still reaches the same record.','&point → p',()=>b.ptr('p','p','t_point *',0x2000,'point'));b.step('p->x = 7;','Write into one field','Follow p to the struct and replace its x field with 7.','The y field remains 2. We display this record as one aggregate memory object.','7 → (*p).x → point.x',()=>b.set('point','{x: 7, y: 2}'),['p'],['point']);return b.finish('printf("%d %d\\n", point.x, point.y);','7 2\n');}
export function buildAdvancedSimulations(){return [allocation(),strdup(),pointerOutput(),concat(),split(),substring(),base(),nonprintable(),argv(),argv(true),callback(),struct()];}
